# test_late_fee.py

from datetime import date

from late_fee import LateFeeCalculator


def calc(today):
    return LateFeeCalculator(today=today)


def test_init_uses_given_today():
    today = date(2026, 1, 20)

    assert calc(today)._today == today


def test_init_uses_real_today_when_none():
    assert LateFeeCalculator()._today == date.today()


def test_zero_or_negative_balance_means_no_fee():
    today = date(2026, 1, 20)
    due = date(2025, 1, 1)

    assert calc(today).compute_fee_cents(0, due) == 0
    assert calc(today).compute_fee_cents(-100, due) == 0


def test_due_date_after_today_means_no_late_days():
    assert calc(date(2026, 1, 10)).compute_fee_cents(
        100_000, date(2026, 1, 11)
    ) == 0


def test_grace_period_means_no_fee():
    # Jan 1 through Jan 14 = 10 weekdays.
    assert calc(date(2026, 1, 15)).compute_fee_cents(
        100_000, date(2026, 1, 1)
    ) == 0


def test_weekends_do_not_count():
    # Jan 2 through Jan 12:
    # Fri, Mon, Tue, Wed, Thu, Fri, Mon = 7 weekdays.
    assert calc(date(2026, 1, 12)).compute_fee_cents(
        100_000, date(2026, 1, 2)
    ) == 0


def test_minimum_fee_applies_after_grace():
    # Jan 1 through Jan 16 = 11 weekdays.
    # One billable day. Raw fee = 5 cents. Min = 500 cents.
    assert calc(date(2026, 1, 16)).compute_fee_cents(
        10_000, date(2026, 1, 1)
    ) == 500


def test_regular_fee():
    # 30 billable weekdays. Fee = 100000 * .015 / 30 * 30 = 1500.
    assert calc(date(2026, 3, 16)).compute_fee_cents(
        100_000, date(2026, 1, 1)
    ) == 15_000


def test_rounds_half_up():
    # One billable day. Raw fee = 1001 * .0005 = 0.5005 cents.
    # Rounded = 1 cent, then minimum fee applies.
    assert calc(date(2026, 1, 16)).compute_fee_cents(
        1_001, date(2026, 1, 1)
    ) == 500


def test_max_fee_cap_applies():
    # Many billable days make raw fee exceed 25% cap.
    assert calc(date(2027, 1, 4)).compute_fee_cents(
        10_000, date(2025, 1, 1)
    ) == 2_500


def test_weekday_helper_handles_reverse_range():
    calculator = calc(date(2026, 1, 10))

    assert calculator._weekday_days_between(
        date(2026, 1, 11),
        date(2026, 1, 10),
    ) == 0


def test_weekday_helper_counts_weekdays_and_skips_weekends():
    calculator = calc(date(2026, 1, 1))

    assert calculator._weekday_days_between(
        date(2025, 12, 26),  # Friday
        date(2025, 12, 30),  # Tuesday; end excluded
    ) == 2  # Friday and Monday
```

